/* Local-only experiment. Production hosts cannot enable it with a URL parameter. */
(function(root){
'use strict';
const local=['localhost','127.0.0.1','[::1]'].includes(root.location?.hostname),enabled=local&&new URLSearchParams(root.location?.search||'').get('features')?.split(',').includes('gamification');
function dateKey(date=new Date()){return [date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-');}
function weekKey(date=new Date()){const monday=new Date(date.getFullYear(),date.getMonth(),date.getDate());monday.setDate(monday.getDate()-(monday.getDay()+6)%7);return dateKey(monday);}
function dateFromKey(key){const [y,m,d]=key.split('-').map(Number);return new Date(y,m-1,d);}
function createTracker(saved={},legacy=[]){
 const data={records:{},sessions:{},...saved};data.records=data.records&&typeof data.records==='object'?data.records:{};data.sessions=data.sessions&&typeof data.sessions==='object'?data.sessions:{};
 data.goals=data.goals&&typeof data.goals==='object'?data.goals:{};data.awards=data.awards&&typeof data.awards==='object'?data.awards:{};
 if(![0,3,5,7].includes(data.weeklyTarget))data.weeklyTarget=5;
 const old=new Set(legacy);
 function weekly(date=new Date()){const week=weekKey(date),end=dateFromKey(week);end.setDate(end.getDate()+7);const count=Object.values(data.records).filter(r=>r.date>=week&&r.date<dateKey(end)).length,target=data.goals[week]??data.weeklyTarget;return {week,count,target,complete:target>0&&count>=target,earned:Boolean(data.awards[week]),trophies:Object.keys(data.awards).length};}
 function award(date){const w=weekly(date);if(w.target>0&&w.count>=w.target&&!w.earned)data.awards[w.week]={target:w.target,date:dateKey(date)};}

 return {data,weekly,setGoal(target,date=new Date()){if(![0,3,5,7].includes(target))return false;data.weeklyTarget=target;data.goals[weekKey(date)]=target;award(date);return true;},begin(record,dailyDate=null){data.sessions[record.id]={help:false,level:record.level,dailyDate};},assist(id){if(data.sessions[id])data.sessions[id].help=true;},finish(record,date=dateKey()){
  const session=data.sessions[record.id];if(old.has(record.id)||data.records[record.id])return false;
  data.records[record.id]={level:record.level,help:session?session.help:null,date,dailyDate:session?.dailyDate||null};award(dateFromKey(date));return true;
 },summary(){const records=Object.values(data.records),ids=new Set([...old,...Object.keys(data.records)]);return {total:ids.size,without:records.filter(r=>r.help===false).length,withHelp:records.filter(r=>r.help===true).length,unknown:[...old].filter(id=>!data.records[id]).length+records.filter(r=>r.help===null).length,levels:new Set(records.map(r=>r.level)).size,days:[...new Set(records.filter(r=>r.dailyDate).map(r=>r.date))]};}};
}
if(typeof module!=='undefined')module.exports={createTracker,dateKey,weekKey};
if(!enabled||typeof document==='undefined')return;
let saved={},legacy=[];try{saved=JSON.parse(localStorage.getItem('sudoku-progress-preview-v1')||'{}');legacy=JSON.parse(localStorage.getItem('sudoku-library-v1')||'{}').completed||[];}catch{}
const tracker=createTracker(saved,legacy);let active=null,storageOK=true;
function persist(){try{localStorage.setItem('sudoku-progress-preview-v1',JSON.stringify(tracker.data));}catch{storageOK=false;}}
const button=document.createElement('button');button.type='button';button.id='my-progress';button.className='progress-launch secondary';button.innerHTML='<span class="goal-icon" aria-hidden="true">◎</span><span class="goal-copy"><strong class="goal-title"></strong><progress class="goal-meter" aria-hidden="true"></progress><span class="goal-caption"></span></span><span class="goal-trophy" aria-hidden="true"></span><span aria-hidden="true">›</span>';document.querySelector('.workspace').before(button);
const dialog=document.createElement('dialog');dialog.id='progress-dialog';dialog.innerHTML='<form method="dialog"><button class="close" aria-label="Zamknij">×</button></form><p class="eyebrow">LOKALNY PROTOTYP</p><h2>Moje postępy</h2><section class="goal-settings"><label for="weekly-goal">Twój cel tygodniowy</label><select id="weekly-goal"><option value="3">3 sudoku</option><option value="5">5 sudoku</option><option value="7">7 sudoku</option><option value="0">Bez celu</option></select><p class="goal-summary" role="status"></p><p class="help">Od poniedziałku do niedzieli. Każda nowa ukończona plansza liczy się tak samo, również z pomocą. Cel możesz zmienić lub wyłączyć.</p></section><details class="progress-details"><summary>Statystyki, osiągnięcia i kalendarz</summary><p class="progress-total"></p><div class="progress-stats"></div><h3>Małe osiągnięcia</h3><ul class="progress-badges"></ul><h3 class="progress-month">Sudoku dnia — ten miesiąc</h3><div class="progress-calendar"></div><p class="help">● Ukończone Sudoku dnia na dowolnym poziomie. Zaznaczamy lokalny dzień ukończenia łamigłówki dnia.</p><p class="help">Bez podpowiedzi: bez ujawniania techniki i bez oznaczania błędów. Obliczanie kandydatów i wypełnianie pojedynczych to zwykłe narzędzia. Wcześniejsze ukończenia mają nieznany sposób rozwiązania. Każda plansza jest liczona raz; ponowne rozwiązanie nie zmienia kategorii.</p></details><p class="progress-storage help"></p>';
document.body.append(dialog);
function paintLaunch(){const w=tracker.weekly(),title=w.target?(w.complete?'Cel tygodnia osiągnięty!':`Cel tygodnia: ${w.count} z ${w.target} sudoku`):'Graj po swojemu — bez celu';button.querySelector('.goal-title').textContent=title;const meter=button.querySelector('.goal-meter');meter.hidden=!w.target;meter.max=w.target||1;meter.value=Math.min(w.count,w.target);button.querySelector('.goal-caption').textContent=w.target?'Moje postępy · ten tydzień':'Moje postępy · ustaw cel, kiedy chcesz';button.querySelector('.goal-trophy').textContent=`🏆 ${w.trophies}`;button.setAttribute('aria-label',`${title}. Zdobyte puchary: ${w.trophies}. Otwórz moje postępy`);}
function paint(){paintLaunch();const w=tracker.weekly();dialog.querySelector('#weekly-goal').value=String(w.target);dialog.querySelector('.goal-summary').textContent=w.complete?`🏆 Cel zrealizowany! Ukończono w tym tygodniu: ${w.count}. Zdobyte puchary: ${w.trophies}.`:w.target?`Ukończono ${w.count} z ${w.target}. ${w.earned?'Zdobyty wcześniej pucharek zachowujesz.':'Pucharek czeka na realizację celu.'}`:`Cel wyłączony. Nadal zapisujemy postępy. Zdobyte puchary: ${w.trophies}.`;const s=tracker.summary();dialog.querySelector('.progress-total').textContent=`${s.total} / 10 000 ukończonych plansz`;dialog.querySelector('.progress-stats').replaceChildren(...[[s.without,'Bez podpowiedzi'],[s.withHelp,'Z pomocą'],[s.unknown,'Wcześniejsze — brak danych']].map(([n,label])=>{const el=document.createElement('div');el.textContent=`${n} · ${label}`;return el;}));dialog.querySelector('.progress-badges').replaceChildren(...[[s.total>=1,'Pierwsza plansza'],[s.total>=10,'Dziesięć ukończonych'],[s.levels===4,'Każdy poziom trudności']].map(([done,label])=>{const el=document.createElement('li');el.textContent=`${done?'✓':'○'} ${label}`;return el;}));const now=new Date(),days=new Date(now.getFullYear(),now.getMonth()+1,0).getDate();dialog.querySelector('.progress-month').textContent='Sudoku dnia — '+new Intl.DateTimeFormat('pl',{month:'long',year:'numeric'}).format(now);dialog.querySelector('.progress-calendar').replaceChildren(...['Pn','Wt','Śr','Cz','Pt','So','Nd'].map(day=>{const el=document.createElement('b');el.textContent=day;return el;}),...Array.from({length:(new Date(now.getFullYear(),now.getMonth(),1).getDay()+6)%7},()=>document.createElement('i')),...Array.from({length:days},(_,i)=>{const el=document.createElement('span'),key=dateKey(new Date(now.getFullYear(),now.getMonth(),i+1)),done=s.days.includes(key);el.textContent=`${i+1}${done?' ●':''}`;el.className=done?'day-done':'';el.setAttribute('aria-label',`${key}${done?' — ukończone Sudoku dnia':''}`);return el;}));dialog.querySelector('.progress-storage').textContent=storageOK?'Dane testowe na tym urządzeniu. Bez konta, synchronizacji i zmian na produkcji.':'Nie udało się zapisać postępów. Dane działają tylko w tej sesji.';}
button.onclick=()=>{paint();dialog.showModal();};
dialog.querySelector('#weekly-goal').onchange=event=>{tracker.setGoal(Number(event.target.value));persist();paint();};tracker.setGoal(tracker.weekly().target);persist();paintLaunch();
root.SudokuProgress={begin(record,dailyDate){tracker.begin(record,dailyDate);persist();},assist(){if(active){tracker.assist(active.id);persist();}},onBoard(record,solved,options={}){active=record;if(!record)return;if(options.errors)tracker.assist(record.id);if(solved)tracker.finish(record);persist();paintLaunch();if(dialog.open)paint();}};
})(globalThis);
